import {setSeconds} from './ensemble-score.mjs';
import {freshWarmEnsemble,ENSEMBLE_DECKS as DECKS,upgradeEnsemble} from './warm-ensemble.mjs';
import {validateWarm} from './warm.mjs';
import {validateEnsemble,validateScene,wavHeader} from './ensemble.mjs';
import {DRUMS,drumPattern,validateDrum} from './drum.mjs';
import {validateProject} from './machine.mjs';
import {validatePaula} from './paula.mjs';
import {validateAcid} from './acid.mjs';
const $=id=>document.getElementById(id),key='small-machines-ensemble-v2',copy=x=>structuredClone(x);
let data=freshWarmEnsemble(),ctx,node,initializing,playing=false,recording=false,selected=0,editBar=0,drumVoice=0,queued=null,state={scene:0,bar:-1,step:-1,meters:[0,0,0,0,0]},recordChunks=[],recordSeconds=0,takeURL,worker,exportChunks=[],intent=0,saveTimer,importTarget;
const tell=(text,error=false)=>{$('status').textContent=text;$('status').dataset.error=String(error);};
try{const raw=localStorage.getItem(key)||localStorage.getItem('small-machines-ensemble-v1');if(raw)data=upgradeEnsemble(validateEnsemble(JSON.parse(raw)));}catch{tell('Das gespeicherte Set konnte nicht geladen werden. Das Originalset ist bereit.',true);}
const send=d=>node?.port.postMessage(d),time=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(key,JSON.stringify(data));$('save-status').textContent='Set und Szenen auf diesem Gerät gespeichert.';}catch{$('save-status').textContent='Speicher voll oder nicht verfügbar. Bitte Set herunterladen.';}},200);}
function mix(patch){Object.assign(data,{...patch,levels:{...data.levels,...patch.levels},mutes:{...data.mutes,...patch.mutes}});send({type:'mix',patch});paintMixer();save();}
const names=['SID/65','PAULA/68','ACID/16','DRUM/08','WARM/06'],captions=['3 SYNTH-STIMMEN / 6502','4 PCM-KANÄLE / 68000','1 STIMME / SLIDE & ACCENT','8 SYNTHETISCHE DRUMS','6 STIMMEN / STEREO-CHORUS'],colors=['#bda1d6','#91b8ce','#adc188','#dfa26e','#e4bd6e'];
const deckEls=[];
DECKS.forEach((deck,i)=>{const el=document.createElement('article');el.className='ensemble-deck';el.style.setProperty('--deck-color',colors[i]);el.innerHTML=`<div class="deck-top"><span>0${i+1}</span><b>${names[i]}</b></div><p class="deck-caption">${captions[i]}</p><div class="deck-level"><input type="range" min="0" max="100" value="100" aria-label="${names[i]} Lautstärke"><output>100%</output></div><div class="deck-meter"><b></b></div><div class="deck-actions"><button data-action="mute" aria-pressed="false">MUTE</button><button data-action="solo" aria-pressed="false">SOLO</button></div><button class="deck-import">↑ Klang & Noten laden</button>`;
 el.querySelector('input').oninput=e=>mix({levels:{[deck]:Number(e.target.value)/100}});el.querySelector('[data-action=mute]').onclick=()=>mix({mutes:{[deck]:!data.mutes[deck]}});el.querySelector('[data-action=solo]').onclick=()=>mix({solo:data.solo===deck?null:deck});el.querySelector('.deck-import').onclick=()=>{importTarget={deck,scene:selected};$('studio-file').click();};$('decks').append(el);deckEls.push(el);});
const sceneEls=[];for(let i=0;i<8;i++){const b=document.createElement('button');b.className='scene-button';b.innerHTML=`<span class="scene-number"><span>0${i+1}</span><span class="scene-length"></span></span><strong></strong><span class="scene-progress"></span>`;b.onclick=()=>launch(i);$('scene-buttons').append(b);sceneEls.push(b);}
function paintMixer(){DECKS.forEach((d,i)=>{const e=deckEls[i];e.querySelector('input').value=Math.round(data.levels[d]*100);e.querySelector('output').textContent=Math.round(data.levels[d]*100)+'%';e.querySelector('[data-action=mute]').setAttribute('aria-pressed',String(data.mutes[d]));e.querySelector('[data-action=solo]').setAttribute('aria-pressed',String(data.solo===d));});$('master').value=data.master*100;$('master-value').textContent=Math.round(data.master*100)+'%';$('filter').value=data.filter*100;$('filter-value').textContent='×'+data.filter.toFixed(2);$('drum-solo').textContent=data.solo==='drums'?'Alle Maschinen hören':'Drums solo hören';}
function paintScenes(){for(let i=0;i<8;i++){const b=sceneEls[i],s=data.scenes[i];b.querySelector('strong').textContent=s.name;b.querySelector('.scene-length').textContent=s.bars+' TAKTE';b.classList.toggle('active',selected===i);b.classList.toggle('queued',queued===i);b.setAttribute('aria-pressed',String(selected===i));b.setAttribute('aria-label',`Szene ${i+1}: ${s.name}, ${s.bars} Takte`);}$('edit-name').value=data.scenes[selected].name;$('scene-bars').value=data.scenes[selected].bars;$('evolution').checked=data.scenes[selected].evolution;$('scene-name').textContent=data.scenes[selected].name;$('bar-readout').textContent=`TAKT ${Math.max(0,state.bar+1)} / ${data.scenes[selected].bars}`;$('queue-state').textContent=queued===null?'WECHSEL AUF DEN NÄCHSTEN TAKT':'ALS NÄCHSTES: '+data.scenes[queued].name;$('duration').textContent=time(setSeconds(data));$('set-name').textContent=data.name;$('drum-edit-scene').textContent=`Szene ${selected+1} · ${data.scenes[selected].name}`;}
function launch(index){if(playing){queued=index;send({type:'queue',index});}else{selected=index;queued=null;state={...state,bar:-1,step:-1};send({type:'queue',index});paintDrums();paintVoice();}paintScenes();tell(playing?'Die Szene startet am nächsten Taktanfang.':'Szene bereit. Play startet sie.');}
function transport(){$('play').textContent=playing?'Ⅱ Anhalten':'▶ '+(ctx?'Spielen':'Einschalten & spielen');$('record').setAttribute('aria-pressed',String(recording));$('record').textContent=recording?'■ '+time(recordSeconds):'● REC';$('export-eight').disabled=!!worker||recording;$('export-full').disabled=!!worker||recording;$('record').disabled=!!worker;$('import-set').disabled=recording;$('display-mode').textContent=playing?($('auto').checked?'SET-ABLAUF / FÜNF MASCHINEN':'LIVE / SZENE WIEDERHOLT SICH'):'BEREIT FÜR DEN NÄCHSTEN TAKT';}
async function audio(){if(initializing)return initializing;if(ctx&&node){await ctx.resume();return;}
 initializing=(async()=>{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Web Audio ist in diesem Browser nicht verfügbar.');ctx=new Audio();await ctx.resume();if(!ctx.audioWorklet)throw Error('Bitte einen Browser mit AudioWorklet-Unterstützung verwenden.');await ctx.audioWorklet.addModule('./ensemble-worklet.mjs');node=new AudioWorkletNode(ctx,'small-ensemble',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[2]});node.port.onmessage=receive;node.connect(ctx.destination);send({type:'load',data});send({type:'queue',index:selected});node.onprocessorerror=()=>{node?.disconnect();node=null;const failed=ctx;ctx=null;void failed.close();playing=false;recording=false;transport();tell('Audio wurde unterbrochen. Bitte erneut einschalten.',true);};ctx.onstatechange=()=>{const live=ctx?.state==='running';$('audio-state').textContent=live?`${(ctx.sampleRate/1000).toFixed(1)} kHz / AUDIO AN`:'AUDIO PAUSIERT';$('audio-led').classList.toggle('on',live);};$('audio-state').textContent=`${(ctx.sampleRate/1000).toFixed(1)} kHz / AUDIO AN`;$('audio-led').classList.add('on');})();
 try{await initializing;}catch(e){node?.disconnect();node=null;if(ctx)await ctx.close();ctx=null;throw e;}finally{initializing=null;}
}
async function start(restart=false){const token=++intent;try{await audio();if(token!==intent)return;$('session-audio').pause();if(restart){send({type:'panic'});selected=0;send({type:'queue',index:0});queued=null;state.bar=-1;paintScenes();paintDrums();paintVoice();}send({type:'play',auto:$('auto').checked});playing=true;transport();tell('Das Ensemble spielt. Regler, Mutes und Szenen sind live.');}catch(e){tell(e.message,true);}}
function stop(){intent++;playing=false;queued=null;send({type:'stop'});state.step=-1;transport();paintScenes();highlight();tell(recording?'Das Set ist gestoppt. REC beendet den Take inklusive Ausklang.':'Gestoppt. Der Klang darf ausklingen.');}
$('play').onclick=()=>playing?stop():start();$('stop').onclick=stop;$('restart').onclick=()=>{if(recording){tell('Bitte den Take beenden, bevor du das Set neu startest.');return;}void start(true);};
$('panic').onclick=()=>{intent++;playing=false;queued=null;send({type:'panic'});state.step=-1;transport();highlight();tell('Sofort stumm.');};
$('auto').onchange=()=>{send({type:'auto',value:$('auto').checked});transport();};
$('bpm').onchange=()=>{data.bpm=Math.round(Math.max(40,Math.min(220,Number($('bpm').value)||128)));$('bpm').value=data.bpm;send({type:'tempo',bpm:data.bpm});paintScenes();save();};
$('master').oninput=()=>mix({master:Number($('master').value)/100});$('filter').oninput=()=>mix({filter:Number($('filter').value)/100});$('drum-solo').onclick=()=>mix({solo:data.solo==='drums'?null:'drums'});
$('record').onclick=async()=>{if(recording){send({type:'recordStop'});return;}try{await audio();recordChunks=[];recordSeconds=0;recording=true;send({type:'record'});if(!playing){$('session-audio').pause();playing=true;send({type:'play',auto:$('auto').checked});}transport();tell('Aufnahme läuft. REC beendet den Take; das Set-Ende beendet ihn mit Ausklang automatisch.');}catch(e){recording=false;transport();tell(e.message,true);}};
function receive(e){const d=e.data;if(d.type==='state'){
  state=d.state;playing=state.playing;recordSeconds=d.recordSeconds;
  if(state.scene!==selected){selected=state.scene;queued=null;paintScenes();paintDrums();paintVoice();}if(queued!==state.pending){queued=state.pending;paintScenes();}
  $('elapsed').textContent=time(state.seconds);$('bar-readout').textContent=`TAKT ${Math.max(0,state.bar+1)} / ${data.scenes[selected].bars}`;sceneEls[selected].querySelector('.scene-progress').style.width=Math.min(100,Math.max(0,(state.bar+(state.step+1)/16)/data.scenes[selected].bars*100))+'%';for(let i=0;i<DECKS.length;i++)deckEls[i].querySelector('.deck-meter b').style.width=Math.min(100,state.meters[i]*260)+'%';transport();highlight();
  if(state.ended)$('display-mode').textContent='LETZTES FENSTER / SET BEENDET';
 }else if(d.type==='chunk')recordChunks.push(d.chunk);
 else if(d.type==='recordDone'){recording=false;transport();if(d.frames){setDownload(new Blob([wavHeader(d.frames,d.rate),...recordChunks],{type:'audio/wav'}),'Live-Take');tell(`Dein Take ist bereit: ${time(d.frames/d.rate)}. Über „Aufnahme herunterladen“ speichern.`);}recordChunks=[];}
 else if(d.type==='error'){playing=false;recording=false;transport();tell(d.message,true);}}
$('save-scene').onclick=()=>{const s=data.scenes[selected];s.name=$('edit-name').value.trim()||'Meine Szene';s.bars=Math.round(Math.max(4,Math.min(128,Number($('scene-bars').value)||32)));s.evolution=$('evolution').checked;send({type:'scene',index:selected,scene:s});save();paintScenes();tell(playing?'Szenenänderung wird am nächsten Takt übernommen.':'Szene gespeichert.');};
const cells=Array.from({length:8},()=>[]),pads=[];
DRUMS.forEach((d,i)=>{const p=document.createElement('button');p.className='drum-pad';p.innerHTML=`<small>0${i+1}</small><strong>${d.name}</strong>`;p.title=d.description;p.onclick=async()=>{drumVoice=i;$('drum-voice').value=i;paintVoice();try{await audio();send({type:'pad',voice:i});p.classList.add('hit');setTimeout(()=>p.classList.remove('hit'),120);}catch(e){tell(e.message,true);}};$('drum-pads').append(p);pads.push(p);$('drum-voice').add(new Option(d.name,String(i)));});
for(let b=0;b<8;b++)$('edit-bar').add(new Option(String(b+1).padStart(2,'0')+' / 08',String(b)));
$('edit-bar').onchange=()=>{editBar=Number($('edit-bar').value);paintDrums();};$('drum-voice').onchange=()=>{drumVoice=Number($('drum-voice').value);paintVoice();};
const corner=document.createElement('span');$('drum-grid').append(corner);for(let st=0;st<16;st++){const n=document.createElement('span');n.className='grid-step-label';n.textContent=String(st+1).padStart(2,'0');$('drum-grid').append(n);}DRUMS.forEach((d,v)=>{const label=document.createElement('span');label.className='grid-row-label';label.innerHTML='<i></i>'+d.name;$('drum-grid').append(label);for(let st=0;st<16;st++){const b=document.createElement('button');b.className='drum-cell'+(st%4===0?' group':'');b.onclick=()=>{const p=data.scenes[selected].patterns[editBar].drums,old=p[v][st],value=old===0?.6:old<.9?1:0;p[v][st]=value;send({type:'drumEdit',scene:selected,bar:editBar,voice:v,step:st,value});paintCell(v,st);save();};$('drum-grid').append(b);cells[v].push(b);}});
function paintCell(v,st){const value=data.scenes[selected].patterns[editBar].drums[v][st],b=cells[v][st];b.classList.toggle('on',value>0);b.classList.toggle('accent',value>=.9);b.setAttribute('aria-pressed',String(value>0));b.setAttribute('aria-label',`${DRUMS[v].name}, Schritt ${st+1}: ${value===0?'aus':value<.9?'leise':'betont'}`);}
function paintDrums(){for(let v=0;v<8;v++)for(let st=0;st<16;st++)paintCell(v,st);highlight();$('drum-edit-scene').textContent=`Szene ${selected+1} · ${data.scenes[selected].name}`;}
function highlight(){for(let v=0;v<8;v++)for(let st=0;st<16;st++)cells[v][st].classList.toggle('current',playing&&state.bar%8===editBar&&state.step===st);}
function paintVoice(){const v=data.scenes[selected].drums.voices[drumVoice];$('drum-level').value=v.level*100;$('drum-level-value').textContent=Math.round(v.level*100)+'%';$('drum-tune').value=v.tune;$('drum-tune-value').textContent=(v.tune>0?'+':'')+v.tune;$('drum-decay').value=v.decay*100;$('drum-decay-value').textContent=Math.round(v.decay*100)+'%';$('drum-mute').setAttribute('aria-pressed',String(v.mute));pads.forEach((p,i)=>p.classList.toggle('selected',i===drumVoice));}
function voiceParam(key,value){data.scenes[selected].drums.voices[drumVoice][key]=value;send({type:'drumVoice',scene:selected,voice:drumVoice,key,value});paintVoice();save();}
for(const key of ['level','tune','decay'])$('drum-'+key).oninput=()=>voiceParam(key,Number($('drum-'+key).value)/(key==='tune'?1:100));$('drum-mute').onclick=()=>voiceParam('mute',!data.scenes[selected].drums.voices[drumVoice].mute);
function sendPattern(){send({type:'scene',index:selected,scene:data.scenes[selected]});save();paintDrums();tell(playing?'Das neue Pattern beginnt am nächsten Takt.':'Drum-Pattern geladen.');}
$('apply-drum').onclick=()=>{data.scenes[selected].patterns[editBar].drums=drumPattern($('drum-preset').value);sendPattern();};$('copy-drum').onclick=()=>{const p=copy(data.scenes[selected].patterns[editBar].drums);for(const bar of data.scenes[selected].patterns)bar.drums=copy(p);sendPattern();};
const safeName=()=>data.name.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,70)||'Small-Machines';
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function setDownload(blob,suffix){if(takeURL)URL.revokeObjectURL(takeURL);takeURL=URL.createObjectURL(blob);$('take-download').href=takeURL;$('take-download').download=safeName()+'-'+suffix+'.wav';$('take-download').textContent='↓ '+suffix+' herunterladen';$('take-download').hidden=false;}
$('export-set').onclick=()=>download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),safeName()+'-Ensemble.json');$('import-set').onclick=()=>$('set-file').click();
$('set-file').onchange=async()=>{try{const f=$('set-file').files[0];if(!f)return;if(f.size>16000000)throw Error('Setdatei zu groß (max. 16 MB).');const next=upgradeEnsemble(validateEnsemble(JSON.parse(await f.text())));intent++;send({type:'panic'});data=next;selected=0;queued=null;playing=false;state={scene:0,bar:-1,step:-1,meters:[0,0,0,0,0]};send({type:'load',data});paintAll();save();tell('Set und acht Szenen geladen.');}catch(e){tell(e.message,true);}finally{$('set-file').value='';}};
$('studio-file').onchange=async()=>{try{const f=$('studio-file').files[0];if(!f)return;if(f.size>12000000)throw Error('Datei zu groß (max. 12 MB).');const raw=JSON.parse(await f.text()),{deck,scene}=importTarget,s=copy(data.scenes[scene]);
 if(deck==='sid'){s.sid=copy(validateProject(raw.sid||raw.set?.sid||raw));for(const p of s.patterns)p.sid=copy(s.sid.patterns);}
 else if(deck==='paula'){s.paula=copy(validatePaula(raw.paula||raw.set?.paula||raw));for(const p of s.patterns)p.paula=copy(s.paula.patterns);}
 else if(deck==='acid'){s.acid=validateAcid(raw);for(const p of s.patterns)p.acid=copy(s.acid.steps);}
 else if(deck==='warm'){s.warm=validateWarm(raw);for(let i=0;i<8;i++)s.patterns[i].warm=copy(s.warm.patterns[i]);s.levels.warm=s.levels.warm||.4;}
 else {s.drums=validateDrum(raw);for(const p of s.patterns)p.drums=copy(s.drums.pattern);}
 validateScene(s);data.scenes[scene]=s;send({type:'scene',index:scene,scene:s});save();paintDrums();paintVoice();tell(names[DECKS.indexOf(deck)]+' in die Szene übernommen'+(playing?' — Wechsel am nächsten Takt.':'.'));
 }catch(e){tell(e.message,true);}finally{$('studio-file').value='';}};
const drumExport=document.createElement('button');drumExport.textContent='↓ Drum-Pattern';drumExport.id='drum-export';drumExport.onclick=()=>download(new Blob([JSON.stringify({...data.scenes[selected].drums,pattern:data.scenes[selected].patterns[editBar].drums},null,2)],{type:'application/json'}),'DRUM08-Pattern.json');$('apply-drum').parentElement.append(drumExport);
function finishExport(){worker?.terminate();worker=null;$('cancel-export').hidden=true;$('export-progress').hidden=true;transport();}
function exportWav(full){if(worker||recording)return;exportChunks=[];$('cancel-export').hidden=false;$('export-progress').hidden=false;$('export-progress').value=0;tell(full?'Das ganze Set wird berechnet. Du kannst hier abbrechen oder weiter spielen.':'Acht Takte werden berechnet.');try{worker=new Worker('./ensemble-render-worker.mjs',{type:'module'});transport();worker.onmessage=e=>{const d=e.data;if(d.type==='chunk'){exportChunks.push(d.chunk);$('export-progress').value=d.progress;}else if(d.type==='done'){setDownload(new Blob([wavHeader(d.frames,d.rate),...exportChunks],{type:'audio/wav'}),full?'Ganzes-Set':'8-Takte');exportChunks=[];finishExport();tell('WAV bereit. Über den Download-Link speichern.');}else if(d.type==='error'){exportChunks=[];finishExport();tell(d.message,true);}};worker.onerror=()=>{exportChunks=[];finishExport();tell('Der Export wurde unterbrochen.',true);};worker.postMessage({data:copy(data),index:selected,full});}catch(e){finishExport();tell(e.message,true);}}
$('export-eight').onclick=()=>exportWav(false);$('export-full').onclick=()=>exportWav(true);$('cancel-export').onclick=()=>{exportChunks=[];finishExport();tell('Export abgebrochen. Dein Set ist unverändert.');};
$('stage').onclick=async()=>{const active=document.body.classList.toggle('stage');$('stage').textContent=active?'Studioansicht ↙':'Bühnenansicht ↗';try{if(active&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(document.fullscreenElement)await document.exitFullscreen();}catch{}drawGarden();};
$('session-audio').onplay=()=>{if(recording){$('session-audio').pause();tell('Bitte zuerst den laufenden Take beenden.');return;}if(playing)stop();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('panic').click();return;}if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,button,a,audio'))return;if(e.code==='Space'){e.preventDefault();$('play').click();}else if(/^[1-8]$/.test(e.key))launch(Number(e.key)-1);});window.addEventListener('pagehide',()=>{intent++;send({type:'panic'});});
function paintAll(){$('bpm').value=data.bpm;paintMixer();paintScenes();paintDrums();paintVoice();transport();$('elapsed').textContent='00:00';}paintAll();
const canvas=$('garden'),g=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let lastDraw=0;
function drawGarden(t=0){const w=canvas.clientWidth,h=canvas.clientHeight,r=Math.min(devicePixelRatio||1,2);if(!w||!h)return;if(canvas.width!==Math.round(w*r)||canvas.height!==Math.round(h*r)){canvas.width=Math.round(w*r);canvas.height=Math.round(h*r);}g.setTransform(r,0,0,r,0,0);g.clearRect(0,0,w,h);g.lineWidth=1;
 for(let j=0;j<DECKS.length;j++){const x=w*(j+.7)/(DECKS.length+.7),level=state.meters?.[j]||0,height=h*(.27+j*.04)+Math.min(h*.38,level*h*1.6);g.strokeStyle=colors[j]+'55';g.beginPath();g.moveTo(x,h*.9);g.lineTo(x,h*.9-height);g.stroke();for(let k=0;k<6;k++){const lit=playing?(k<(state.step+j*3+16)%7):k===j%6;const drift=reduced?0:Math.sin(t/1100+j+k)*level*7;g.fillStyle=colors[j]+(lit?'dd':'28');g.fillRect(x-13+(k%2)*15+drift,h*.85-height+k*height/7,9,Math.max(3,height/11));}g.strokeStyle=colors[j]+'99';g.beginPath();for(let n=0;n<50;n++){const px=x-28+n/49*56,py=h*.93+Math.sin(n*.4+(reduced?0:t/300))*level*18;n?g.lineTo(px,py):g.moveTo(px,py);}g.stroke();}
}
function animate(t){if(!document.hidden&&t-lastDraw>45){drawGarden(t);lastDraw=t;}requestAnimationFrame(animate);}requestAnimationFrame(animate);

$('warm-transfer').onclick=()=>{try{const raw=localStorage.getItem('small-machines-warm-transfer');if(!raw)throw Error('Zuerst im WARM/06-Studio einen Klang übergeben.');const project=validateWarm(JSON.parse(raw)),s=copy(data.scenes[selected]);s.warm=project;s.levels.warm=s.levels.warm||.4;for(let i=0;i<8;i++)s.patterns[i].warm=copy(project.patterns[i]);validateScene(s);data.scenes[selected]=s;send({type:'scene',index:selected,scene:s});save();tell('WARM/06 mit Klang und acht Takten übernommen'+(playing?' — ab dem nächsten Takt.':'.'));}catch(e){tell(e.message,true);}};
